/**
 * Regenerate the compiled-in prompt artifacts
 * (docs/specs/artifact-resolution-in-production.spec.md, workstream 1).
 *
 * Reads packages/llm/prompts/*.prompt.yaml and emits
 * packages/llm/src/prompt/artifacts/builtins.generated.ts, so production
 * can resolve a per-model variant without touching the filesystem.
 *
 * The generated file is committed. Three distribution shapes make
 * runtime loading unworkable: the published npm package ships `dist`
 * only (`files: ["dist"]`), the VS Code extension is an esbuild CJS
 * bundle where `import.meta.url` already misbehaves, and a global CLI
 * install has no predictable path to a sibling prompts/ directory.
 * Compiling the artifacts in sidesteps all three.
 *
 * Committed rather than gitignored so a consumer reading dist can trace
 * provenance without running the build; a drift test keeps it honest,
 * mirroring how docs/tutorial/ and examples/output/ are guarded.
 *
 * Usage: npm run regen:builtins   (from barwise/)
 */
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const llmRoot = resolve(here, "../packages/llm");

const { loadArtifactsFromDir } = await import(
  resolve(llmRoot, "dist/prompt/artifacts/loadArtifact.js")
);

const artifacts = loadArtifactsFromDir(resolve(llmRoot, "prompts"));

/**
 * The loader is the single source of truth for shape and validation, so
 * the emitted file is a serialization of what it produced -- not a
 * second parser with its own opinions.
 */
const body = artifacts
  .map((a) => JSON.stringify(a, null, 2).replace(/^/gm, "  ").trimStart())
  .join(",\n  ");

const out = `// Generated by scripts/regen-builtin-artifacts.mjs -- do not edit.
// Source: packages/llm/prompts/*.prompt.yaml
// Regenerate with \`npm run regen:builtins\` from barwise/ and review the diff.
//
// Compiled in rather than read from disk: the published package ships
// dist only, the VS Code bundle breaks import.meta.url, and a global CLI
// install has no path to a sibling prompts/ directory.
import type { PromptArtifact } from "./PromptArtifact.js";

/** Every checked-in variant, in filename order. */
export const builtinArtifacts: readonly PromptArtifact[] = [
  ${body},
];
`;

const target = resolve(llmRoot, "src/prompt/artifacts/builtins.generated.ts");
writeFileSync(target, out);
console.log(
  `Wrote ${artifacts.length} built-in artifact(s) to ${target.replace(resolve(here, ".."), ".")}`,
);
for (const a of artifacts) {
  const m = a.match ?? {};
  console.log(
    `  ${a.surface}/${a.version}  provider=${m.provider ?? "-"} modelPrefix=${
      m.modelPrefix ?? "-"
    }`,
  );
}
